{"name": "get_node", "description": "Read a node by id with depth-limited descendants.", "inputSchema": {"type": "object", "properties": {"node_id": {"type": "string", "description": "u64 node id"}}, "required": ["node_id"]}}
{"name": "list_pages", "description": "List page ids + names. Result includes page_count, active_page_index, ids, and names as comma-separated strings.", "inputSchema": {"type": "object", "properties": {"filePath": {"type": "string", "description": "Optional target .op file path; omit to use the server document"}}}}
{"name": "lint_document", "description": "Run first-class OpenPencil design lint over the active document. Optionally filter to a node subtree.", "inputSchema": {"type": "object", "properties": {"nodeId": {"type": "string", "description": "Optional node id to filter issues to that node and descendants"}}}}
{"name": "export_design_md", "description": "Export design.md markdown, falling back to best-effort extraction when none is persisted.", "inputSchema": {"type": "object", "properties": {"filePath": {"type": "string", "description": "Optional target .op file path; omit to use the server document"}}}}
{"name": "get_screenshot", "description": "Render a node to a PNG image for visual verification. nodeId may be \"root\" for the active page's top node.", "inputSchema": {"type": "object", "properties": {"nodeId": {"type": "string", "description": "Node id, or \"root\""}}, "required": ["nodeId"]}}
{"name": "export_item", "description": "Export a page, arbitrary node, or current selection to base64-encoded image/PDF bytes.", "inputSchema": {"type": "object", "properties": {"itemId": {"type": "string"}, "format": {"type": "string", "enum": ["png", "jpeg", "webp", "pdf"]}, "scale": {"type": "number"}}, "required": ["format"]}}
{"name": "export_nodes", "description": "Export one or more nodes to base64-encoded image/PDF bytes. format is one of png|jpeg|webp|pdf.", "inputSchema": {"type": "object", "properties": {"nodeIds": {"type": "array", "items": {"type": "string"}}, "format": {"type": "string", "enum": ["png", "jpeg", "webp", "pdf"]}, "scale": {"type": "number"}}, "required": ["nodeIds", "format"]}}
{"name": "export_deck", "description": "Export the active page's boards as a presentation deck in PowerPoint, self-contained HTML, or PDF. Writes a file at outputPath; use export_item/export_nodes for base64 node-level exports.", "inputSchema": {"type": "object", "properties": {"format": {"type": "string", "enum": ["pptx", "html", "pdf"]}, "outputPath": {"type": "string", "description": "Destination file path for the deck"}}, "required": ["format", "outputPath"]}}
{"name": "export_frames", "description": "Export every top-level frame on the active page into a directory, one image per frame, using the editor's own file naming.", "inputSchema": {"type": "object", "properties": {"outputDir": {"type": "string", "description": "Destination directory; created if absent"}, "format": {"type": "string", "enum": ["png", "jpeg", "webp"], "default": "png"}}, "required": ["outputDir"]}}
{"name": "read_nodes", "description": "Read nodes with depth control. Omit nodeIds to return top-level page children; depth=0 truncates children to \"...\", depth=-1 returns full subtrees. includeVariables=true attaches variables/themes JSON strings.", "inputSchema": {"type": "object", "properties": {"filePath": {"type": "string", "description": "Optional target .op file path; omit to use the server document"}, "nodeIds": {"type": "array", "items": {"type": "string"}, "description": "Node ids to read; omit for top-level children"}, "depth": {"type": "number", "description": "0=node only, 1=direct children, -1=full subtree"}, "pageId": {"type": "string"}, "includeVariables": {"type": "boolean"}}}}
{"name": "add_node_effect", "description": "Append a visual effect to a node with default parameters. kind is shadow / blur / background_blur. Frame/Group/Rectangle and the leaf shapes accept effects; IconFont/Ref do not.", "inputSchema": {"type": "object", "properties": {"node_id": {"type": "string"}, "kind": {"type": "string", "enum": ["shadow", "blur", "background_blur"]}}, "required": ["node_id", "kind"]}}
{"name": "toggle_node_selection", "description": "Shift-click parity: toggle node_id in the multi-selection (scoped to the ACTIVE page only). Already-selected ⇒ remove (anchor reassigns to last surviving id); otherwise add as new anchor. Rejects unknown ids and ids that live on a non-active page.", "inputSchema": {"type": "object", "properties": {"node_id": {"type": "string", "description": "positive u64 node id on the active page"}}, "required": ["node_id"]}}
{"name": "add_page", "description": "Append a fresh page and switch the active page to it. Optional name and children mirror the TS MCP page tool. Returns false on id-space exhaustion or an empty name.", "inputSchema": {"type": "object", "properties": {"filePath": {"type": "string", "description": "Optional target .op file path; omit to use the server document"}, "name": {"type": "string", "description": "Page name (default: Page N)"}, "children": {"type": "array", "items": {"type": "object"}, "description": "Initial child nodes for the new page; omitted creates the default blank frame"}}}}

