curl -sS -X POST http://127.0.0.1:3100/mcp -H 'Content-Type: application/json' -H 'Accept: application/json, text/event-stream' -H 'mcp-session-id: openpencil' --data '{"jsonrpc":"2.0","id":15,"method":"tools/call","params":{"name":"read_nodes","arguments":{"nodeIds":["n2082"],"depth":-1,"pageId":"n2081"}}}' | python3 -c 'import sys,json,itertools; r=json.load(sys.stdin); root=json.loads(r["result"]["content"][0]["text"])["nodes"][0]; ns=[]

def walk(n):
 ns.append(n)
 for c in n.get("children",[]): walk(c)
walk(root); print("ROOT",root["id"],root["width"],root["height"],"NODES",len(ns)); print("FONT_LT_12",[(n["id"],n.get("name"),n.get("fontSize"),n.get("content")) for n in ns if n.get("type")=="text" and n.get("fontSize",99)<12]); print("HIDDEN",[(n["id"],n.get("name")) for n in ns if n.get("hidden")]); print("OOB",[(n["id"],n.get("name"),n.get("x"),n.get("y"),n.get("width"),n.get("height")) for n in ns[1:] if n.get("x",0)<0 or n.get("y",0)<0 or n.get("x",0)+n.get("width",0)>root["width"] or n.get("y",0)+n.get("height",0)>root["height"]])'

