import struct,zlib
for path in ['/tmp/op-n2033.png','/tmp/op-n2082.png','/tmp/op-n2137.png','/tmp/op-n2192.png']:
 b=open(path,'rb').read(); p=8; chunks=[]
 while p<len(b):
  n=struct.unpack('>I',b[p:p+4])[0]; t=b[p+4:p+8]; d=b[p+8:p+8+n]; p+=12+n
  if t==b'IHDR': w,h,bd,ct,_,_,_=struct.unpack('>IIBBBBB',d)
  if t==b'IDAT': chunks.append(d)
 raw=zlib.decompress(b''.join(chunks)); bpp=4; stride=w*bpp; rows=[]; q=0; prev=bytearray(stride)
 for y in range(h):
  f=raw[q]; q+=1; cur=bytearray(raw[q:q+stride]); q+=stride
  for i in range(stride):
   a=cur[i-bpp] if i>=bpp else 0; bb=prev[i]; c=prev[i-bpp] if i>=bpp else 0
   if f==1: cur[i]=(cur[i]+a)&255
   elif f==2: cur[i]=(cur[i]+bb)&255
   elif f==3: cur[i]=(cur[i]+((a+bb)//2))&255
   elif f==4:
    pp=a+bb-c; pa=abs(pp-a); pb=abs(pp-bb); pc=abs(pp-c); cur[i]=(cur[i]+(a if pa<=pb and pa<=pc else bb if pb<=pc else c))&255
  rows.append(cur); prev=cur
 def px(x,y): return tuple(rows[y][x*4:x*4+4])
 print(path,w,h,[(xy,px(*xy)) for xy in [(10,100),(100,100),(100,500),(230,100),(244,100),(10,500)]])
